def is_valid_amount(v):
    return isinstance(v, int) and not isinstance(v, bool) and v > 0

billable = []
rejected = []
rows = input if isinstance(input, list) else []
for row in rows:
    if not isinstance(row, dict):
        rejected.append({"row": row, "reason": "not_an_object"})
        continue
    email = row.get("email")
    amt = row.get("amount_cents")
    if not isinstance(email, str) or not email.strip():
        rejected.append({"row": row, "reason": "missing_email"})
        continue
    if not is_valid_amount(amt):
        rejected.append({"row": row, "reason": "invalid_amount"})
        continue
    billable.append({"email": email.strip(), "amount_cents": amt})
output = {"billable": billable, "rejected": rejected}

do = input.get("dedup_output") or {}
vo = input.get("validate_output") or {}
clean = do.get("clean") or []
skipped = do.get("skipped") or []
rejected = vo.get("rejected") or []
total_cents = sum(int(c.get("amount_cents") or 0) for c in clean)
ceiling = input.get("spend_ceiling_cents")
within_cap = isinstance(ceiling, int) and not isinstance(ceiling, bool) and total_cents <= ceiling
output = {"billable_count": len(clean), "skipped_count": len(skipped), "rejected_count": len(rejected), "total_cents": total_cents, "spend_ceiling_cents": ceiling, "within_cap": within_cap, "proceed": bool(clean) and within_cap}

clean = input.get("clean") or []
records = []
for index, row in enumerate(clean):
    record = {"record_ref": "batch-" + str(index + 1), "amount_cents": int(row.get("amount_cents") or 0), "invoice_count": 1}
    baseline = input.get("portfolio_baseline_cents")
    if isinstance(baseline, int) and not isinstance(baseline, bool) and baseline > 0:
        record["prior_amount_cents"] = baseline
    records.append(record)
output = {"billing_period": str(input.get("billing_period") or ""), "portfolio": records, "portfolio_baseline_cents": input.get("portfolio_baseline_cents") or 0}

